var builder = WebApplication.CreateBuilder(args);

// Register the MCP server with HTTP (Streamable HTTP) transport.
// WithToolsFromAssembly / WithResourcesFromAssembly scan for
// [McpServerToolType] and [McpServerResourceTemplate] in this assembly.
builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();

// MapMcp exposes the MCP endpoint at /mcp (default).
// Clients POST JSON-RPC requests here; the server responds over
// Streamable HTTP (SSE / chunked).
app.MapMcp();

app.Run();

