using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

// Resources are exposed via [McpServerResource] on a static method.
// The URI template lets clients discover and read this resource.
[McpServerResourceTemplate(UriTemplate = "config://app/{section}",
    Name = "Application Configuration",
    Description = "Returns configuration data for the requested section")]
public static class ConfigResource
{
    private static readonly Dictionary<string, Dictionary<string, string>> Sections = new()
    {
        ["general"] = new()
        {
            ["appName"] = "McpHttpServer",
            ["version"] = "1.0.0",
            ["environment"] = "production"
        },
        ["limits"] = new()
        {
            ["maxRequestsPerMinute"] = "100",
            ["maxPayloadSizeKb"] = "512",
            ["timeoutSeconds"] = "30"
        }
    };

    [McpServerResource]
    [Description("Read configuration for a given section")]
    public static string ReadConfig(string section)
    {
        if (Sections.TryGetValue(section.ToLowerInvariant(), out var values))
        {
            return System.Text.Json.JsonSerializer.Serialize(values,
                new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
        }

        return $"Unknown config section: {section}";
    }
}

